"""The bootstrap reproduces packages/fixtures/reference-results/pls-bootstrap (generated by
make_bootstrap_references.R with cSEM::csem per draw): every draw's index stream, status,
failure reason / failed verify() checks and parameter vector (<= 1e-10), and every SE / t / p /
CI of estimate()."""

import os

import pytest
from helpers import REF, analysis_data, load_case, read_json

DIR = REF / "pls-bootstrap"
FILES = sorted(f for f in os.listdir(DIR) if f.endswith(".json"))
TOL = 1e-10


def _setup(ref):
    model, header, rows = load_case(ref["case"])
    data = analysis_data(ref["request"]["model"], header, rows[: ref["rows"]])
    analysis = dict(ref["request"]["analysis"], engine="browser")
    return data, analysis


def test_has_the_reference_files():
    for f in (
        "tam-mediation__pls-sem.json",
        "tam-mediation__plsc.json",
        "pls-mixed-composite__pls-sem.json",
        "delone-mclean__pls-sem.json",
    ):
        assert f in FILES


@pytest.mark.parametrize("file", FILES)
def test_every_draw(eng, devlog, file):
    report = f"PLS bootstrap vs R reference, {len(FILES)} files ({eng.__name__})"
    ref = read_json(DIR / file)
    data, analysis = _setup(ref)
    spec = eng.validate_request(ref["request"]["model"], analysis)
    prepared = eng.pls_prepare_data(spec, data)
    theta = eng.theta_entries(spec)
    assert [t.key for t in theta] == ref["thetaKeys"]
    problem = eng.BootstrapProblem(eng.core_model(spec), spec.method == "plsc", prepared.X, theta)
    results = []
    for b, idx in enumerate(eng.bootstrap_indices(ref["seed"], prepared.n, ref["B"])):
        r = ref["draws"][b]
        assert int(idx.sum()) + len(idx) == r["idxSum"], f"draw {r['b']} index stream"
        d = eng.fit_draw(problem, idx)
        results.append(d)
        assert d.status == r["status"], f"draw {r['b']}"
        if d.status == "failed":
            assert d.reason == r["reason"], f"draw {r['b']}"
        if d.status == "inadmissible":
            assert d.checks == r["checks"], f"draw {r['b']}"
        if d.status in ("ok", "inadmissible"):
            fam = "draw estimates (valid)" if d.status == "ok" else "draw estimates (inadmissible)"
            for i, v in enumerate(d.theta):
                dev = abs(v - r["theta"][i])
                devlog.track(report, fam, dev, f"{file} draw {r['b']}")
                assert dev <= TOL, f"draw {r['b']} {ref['thetaKeys'][i]}"
    counts = eng.summarise_bootstrap(results)
    assert {
        "requested": counts.requested,
        "completed": counts.completed,
        "failed": counts.failed,
        "inadmissible": counts.inadmissible,
    } == ref["counts"]


@pytest.mark.parametrize("file", FILES)
def test_inference(eng, devlog, file):
    report = f"PLS bootstrap vs R reference, {len(FILES)} files ({eng.__name__})"
    ref = read_json(DIR / file)
    data, analysis = _setup(ref)
    out = eng.estimate(ref["request"]["model"], analysis, data)
    assert out["ok"], out.get("error")
    bs = out["result"]["bootstrap"]
    assert {k: bs[k] for k in ("requested", "completed", "failed", "inadmissible")} == ref["counts"]
    assert bs["seed"] == ref["seed"]
    by_key = {p["key"]: p for p in out["result"]["parameters"]}
    for rp in ref["parameters"]:
        tp = by_key[rp["key"]]
        assert (tp.get("inference") or {}).get("nValid") == rp["nValid"], rp["key"]
        for field, fam in (
            ("est", "estimates"),
            ("se", "se"),
            ("statistic", "t"),
            ("pValue", "p"),
            ("ciLower", "CI"),
            ("ciUpper", "CI"),
        ):
            a, b = tp[field], rp[field]
            if a is None or b is None:
                assert a == b, f"{rp['key']} {field}"
                continue
            d = abs(a - b)
            devlog.track(report, fam, d, f"{file} {rp['key']}")
            assert d <= TOL, f"{rp['key']} {field}: {a} vs {b}"
